export const barangaysForCity = (city: string): string[] => {
  const key = Object.keys(BARANGAYS_BY_CITY).find((c) => c.toLowerCase() === String(city||'').trim().toLowerCase());
  if (!key) return [];
  return BARANGAYS_BY_CITY[key].map((r) => r.barangay);
};
